begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values ('f0000000-0000-4000-8000-000000003461','duplicate-type@example.test',now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000003461","role":"authenticated"}';
select set_config('test.tenant',create_tenant('Synthetic types','synthetic-duplicate-types',gen_random_uuid())::text,true);
select set_config('test.id',gen_random_uuid()::text,true);
select lives_ok(format('select create_item_type(%L,%L,%L,%L,%L)',current_setting('test.tenant'),current_setting('test.id'),'Synthetic vessel','en','[{"slug":"description","expected":true,"sort":0}]'),'first name creates a type');
select lives_ok(format('select create_item_type(%L,%L,%L,%L,%L)',current_setting('test.tenant'),current_setting('test.id'),'Synthetic vessel','en','[{"slug":"description","expected":true,"sort":0}]'),'exact replay is checked before name collision');
select throws_ok(format('select create_item_type(%L,%L,%L,%L,%L)',current_setting('test.tenant'),gen_random_uuid(),'  SYNTHETIC VESSEL  ','sv','[{"slug":"description","expected":true,"sort":0}]'),'P0001','ITEM_TYPE_NAME_EXISTS','case and outer whitespace cannot create another name');
select set_item_type(current_setting('test.tenant')::uuid,'synthetic_inactive','{"labels":{"en":"Inactive vessel","sv":"Testkanna"},"active":false,"attributes":[{"slug":"description","expected":true,"sort":0}]}');
select throws_ok(format('select create_item_type(%L,%L,%L,%L,%L)',current_setting('test.tenant'),gen_random_uuid(),'testkanna','en','[{"slug":"description","expected":true,"sort":0}]'),'P0001','ITEM_TYPE_NAME_EXISTS','inactive and translated labels also reserve the name');
select throws_ok(format('select create_item_type(%L,%L,%L,%L,%L)',current_setting('test.tenant'),gen_random_uuid(),'Jacket','en','[{"slug":"description","expected":true,"sort":0}]'),'P0001','ITEM_TYPE_NAME_EXISTS','effective platform labels cannot be duplicated');
select is((select count(*) from item_types where tenant_id=current_setting('test.tenant')::uuid and slug like 'custom_%'),1::bigint,'refused duplicates leave no records');
select set_config('test.other',create_tenant('Synthetic other types','synthetic-other-types',gen_random_uuid())::text,true);
select lives_ok(format('select create_item_type(%L,%L,%L,%L,%L)',current_setting('test.other'),gen_random_uuid(),'Synthetic vessel','en','[{"slug":"description","expected":true,"sort":0}]'),'names remain tenant scoped');
select * from finish();
rollback;
